/** The three signature skills of each class, in §4.5 table order (the three cards of the Beceri Uzmanlıkları tab, §5.4). */
export const SIGNATURE_SKILLS: Record<ClassId, string[]> = {
  knight: ['knight_shield_bash', 'knight_radiant_cleave', 'knight_consecration'],
  barbarian: ['barbarian_cleave', 'barbarian_whirlwind', 'barbarian_leap'],
  mage: ['mage_fireball', 'mage_frost_nova', 'mage_arcane_orb'],
  rogue: ['rogue_crossbow_shot', 'rogue_fan_of_knives', 'rogue_shadow_step'],
  monk: ['monk_tiger_palm', 'monk_blackout_kick', 'monk_chi_wave'],
  archer: ['archer_aimed_shot', 'archer_multishot', 'archer_explosive_arrow'],
  paladin: ['paladin_crusader_strike', 'paladin_judgement', 'paladin_avengers_shield'],
  necromancer: ['necro_bone_spear', 'necro_raise_skeleton', 'necro_corpse_explosion'],
  warlock: ['warlock_shadow_bolt', 'warlock_corruption', 'warlock_drain_life'],
  // CM1 stubs: the new classes' signature skills come with their kits (CM10 / CM12).
  demonhunter: [],
  evoker: [],
};

/** The six options (tier 1 A, 1 B, 2 A, 2 B, 3 A, 3 B) of one signature skill; [] for an unknown skill id. */
export function skillSpecsOf(skillId: string): SkillSpecRow[] {
  return SKILL_SPEC_ROWS.filter((r) => r.skill === skillId);
}
